code='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); frames=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0>=2 and c1-c0>=2:
                border={(r0,x) for x in range(c0,c1+1)} | {(r1,x) for x in range(c0,c1+1)} | {(y,c0) for y in range(r0,r1+1)} | {(y,c1) for y in range(r0,r1+1)}
                if all(grid[y][x]==color for y,x in border) and set(cells)==border:
                    frames.append((r0,r1,c0,c1,color,border))
    noise=Counter(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] and not any((r,c) in f[5] for f in frames))
    out=[[0]*w for _ in range(h)]
    for r0,r1,c0,c1,color,border in frames:
        for r,c in border: out[r][c]=color
    for r0,r1,c0,c1,color,border in frames:
        n=sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1) if (r-r0-1+c-c0-1)%2==0)
        fill=next((col for col,count in noise.items() if count==n),None)
        if fill is not None:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if (r-r0-1+c-c0-1)%2==0: out[r][c]=fill
    return out
'''
